/** @jsxImportSource @opentui/solid */
// Live day/night inside a running `parker code`.
//
// The theme parker code wears is generated from the active Stylix scheme
// (code.nix), which means it is regenerated by the *specialisation switch* —
// base system is night/redline, the `day` specialisation is hangar, and
// `theme light|dark|sync` flips between them in seconds. Home-manager rewrites
// ~/.config/opencode/themes/parker.json on the way through.
//
// opencode reads that file once, at startup. So before this plugin, a flip at
// 08:00 left every open session on last night's palette until it was
// restarted — the one seam in the day/night system that a rebuild could not
// close, because the process outlives the rebuild.
//
// The fix is small: watch the generated theme file, and when its contents
// change, re-install and re-select it. No polarity detection, no reading of
// /run/current-system — the file *is* the signal, and it is already exactly
// as correct as the rest of the theming chain.
//
// Polling rather than fs.watch on purpose: home-manager swaps the symlink
// rather than writing through it, which is precisely the case inotify-style
// watches miss. A 4-second stat of one small file is not worth optimising.
import type { TuiPlugin, TuiPluginApi, TuiPluginModule } from "@opencode-ai/plugin/tui"
import { execFile } from "node:child_process"
import { readFileSync } from "node:fs"
import { homedir } from "node:os"
import { join } from "node:path"

const THEME_NAME = "parker"
const THEME_PATH = join(homedir(), ".config", "opencode", "themes", "parker.json")
const POLL_MS = 4000

const tui: TuiPlugin = async (api: TuiPluginApi) => {
  // The contents at startup, not a timestamp: home-manager writes store
  // symlinks whose mtime is always 1970, so mtime is useless here and the
  // file is a few hundred bytes.
  const read = () => {
    try {
      return readFileSync(THEME_PATH, "utf8")
    } catch {
      return null
    }
  }

  let last = read()

  const apply = async (why: string) => {
    try {
      await api.theme.install(THEME_PATH)
      await api.theme.set(THEME_NAME)
      api.ui.toast?.({
        title: "parker",
        message: `${why} — now ${api.theme.mode()}`,
      })
    } catch {
      // A failed re-theme is cosmetic. Never take the session down for it:
      // parker is not in the critical path (PARKER.md invariant 1).
    }
  }

  const timer = setInterval(() => {
    const now = read()
    if (now === null || now === last) return
    last = now
    void apply("theme flipped")
  }, POLL_MS)

  api.lifecycle.onDispose(() => clearInterval(timer))

  // Flipping polarity by hand. Deliberately a palette command with no default
  // keybind: `theme light|dark|sync` triggers a specialisation activation that
  // repaints the whole desktop, which is too much to hang off a stray chord.
  api.keymap.registerLayer({
    commands: [
      {
        name: "parker.theme.day",
        title: "parker: day (hangar)",
        category: "parker",
        namespace: "palette",
        slashName: "day",
        run: () => execFile("theme", ["light"], () => {}),
      },
      {
        name: "parker.theme.night",
        title: "parker: night (redline)",
        category: "parker",
        namespace: "palette",
        slashName: "night",
        run: () => execFile("theme", ["dark"], () => {}),
      },
      {
        name: "parker.theme.sync",
        title: "parker: follow the clock",
        category: "parker",
        namespace: "palette",
        slashName: "sync",
        run: () => execFile("theme", ["sync"], () => {}),
      },
    ],
    bindings: [],
  })
}

const plugin: TuiPluginModule = { id: "parker.theme", tui }

export default plugin
